:root{--mint:#1b8168;--mint-soft:#d8f0e6;--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--teal-soft:#d9ecec;--danger:#b23b3b;--danger-soft:#f6e4e2;--lime-soft:#eaf2ce}
body{background:var(--stage);font-family:system-ui,-apple-system,'Segoe UI',sans-serif;color:var(--ink)}
.wrap{display:flex;flex-wrap:wrap;gap:24px;padding:24px;align-items:flex-start}
.phone{width:380px;background:var(--cream);border-radius:28px;padding:18px 16px;box-shadow:0 2px 10px rgb(0 0 0/.06)}
.state{font-size:11px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-soft);margin:0 0 8px}
h1{font-size:22px;font-weight:900;margin:4px 0 14px}
.back{font-size:13px;font-weight:700;color:var(--ink-soft)}
.card{border:1px solid var(--line);background:var(--paper);border-radius:22px;padding:18px}
.lbl{display:block;font-size:11px;font-weight:800;letter-spacing:.03em;color:var(--ink-soft);margin:12px 0 5px}
.lbl .req{color:var(--danger)}
.in{width:100%;box-sizing:border-box;border:1.5px solid var(--line-strong);border-radius:12px;padding:10px 12px;font-size:14px;background:var(--paper);color:var(--ink)}
.in.ph{color:#9aa9a2}
.in.err{border-color:var(--danger)}
.in.focus{border-color:var(--mint);box-shadow:0 0 0 3px var(--mint-soft)}
.help{font-size:12.5px;color:var(--ink-soft);margin:5px 0 0}
.error{font-size:12.5px;font-weight:600;color:var(--danger);margin:5px 0 0}
.lb{border:1.5px solid var(--line-strong);border-radius:12px;margin-top:4px;background:var(--paper);overflow:hidden}
.opt{padding:8px 12px;font-size:13.5px;border-bottom:1px solid var(--line)}
.opt:last-child{border-bottom:0}
.opt b{font-weight:800}
.opt small{display:block;color:var(--ink-soft);font-size:12px}
.opt.active{background:var(--mint-soft)}
.chip{display:flex;justify-content:space-between;align-items:center;border:1.5px solid var(--mint);background:var(--mint-soft);border-radius:12px;padding:9px 12px;font-size:13.5px}
.chip small{display:block;color:var(--ink-soft);font-size:12px}
.chip button{border:0;background:none;font-weight:800;color:var(--ink-soft);font-size:12px}
.row{display:flex;gap:8px;margin-top:16px}
.btn{border-radius:9px;padding:9px 14px;font-size:13px;font-weight:800;border:0}
.save{background:var(--mint);color:#fff}
.cancel{background:transparent;border:1px solid var(--line);color:var(--ink-soft)}
.disabled{opacity:.55}
.pick{display:flex;gap:8px;align-items:center}
.pick select,.pick .sel{flex:1}
.add{flex:none;width:40px;height:40px;border-radius:12px;background:var(--mint);color:#fff;font-weight:900;font-size:20px;display:flex;align-items:center;justify-content:center;text-decoration:none}
.photos{display:flex;gap:8px}
.ph-box{width:64px;height:64px;border-radius:14px;background:var(--lime-soft);border:1.5px dashed var(--line-strong);display:flex;align-items:center;justify-content:center;color:var(--ink-soft);font-size:22px}
.ph-box.img{background:linear-gradient(135deg,#cfe3d6,#a9c24f);border-style:solid}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}
.act{border-radius:14px;padding:12px;font-weight:800;font-size:14px;text-align:center;border:0}
.gift{background:var(--mint);color:#fff}.swap{background:var(--teal-soft);color:var(--ink)}
.draft{grid-column:span 2;background:transparent;border:1.5px solid var(--line-strong);color:var(--ink)}
.banner{background:var(--lime-soft);border-radius:14px;padding:10px 12px;font-size:13px;font-weight:600;margin-bottom:12px}
.banner.warn{background:var(--danger-soft);color:var(--danger)}
.loc{display:flex;gap:10px;align-items:flex-start}
.pin{width:34px;height:34px;border-radius:10px;background:var(--mint-soft);display:flex;align-items:center;justify-content:center;flex:none}
.loc b{display:block;font-size:14.5px}
.loc span{font-size:12.5px;color:var(--ink-soft)}
.link{font-size:12.5px;font-weight:800;color:var(--mint);text-decoration:underline}
.own{margin-top:10px;border-top:1px dashed var(--line-strong);padding-top:10px;font-size:13px}
.own em{font-style:normal;font-size:11px;font-weight:800;color:var(--ink-soft);display:block;text-transform:uppercase;letter-spacing:.05em}
.prow{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid var(--line)}
.prow:last-child{border-bottom:0}
.prow b{display:block;font-size:14px}
.prow span{font-size:12.5px;color:var(--ink-soft)}
.prow .acts{font-size:12px;font-weight:800;color:var(--ink-soft)}
.top{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--ink-soft)}

